import keytar from "keytar";
import { requestDeviceCode, pollForToken } from "../auth/device.js";
import { log } from "../log.js";

const SERVICE = "acme-cli";

export async function login(opts: { profile: string }) {
  const code = await requestDeviceCode();
  log.info(`Go to ${code.verification_uri} and enter ${code.user_code}`);

  let token: string | undefined;
  while (!token) {
    await new Promise((r) => setTimeout(r, code.interval * 1000));
    log.info("polling...");
    const res = await pollForToken(code.device_code);
    if (res.status === "ok") token = res.access_token;
  }

  await keytar.setPassword(SERVICE, opts.profile, token);
  log.info("logged in");
}

export type PollResult =
  | { status: "ok"; access_token: string }
  | { status: "pending" }
  | { status: "slow_down" }
  | { status: "expired" }
  | { status: "denied" };

export async function requestDeviceCode() {
  const res = await fetch(`${AUTH_BASE}/oauth/device/code`, {
    method: "POST",
    body: new URLSearchParams({ client_id: CLIENT_ID, scope: "openid offline_access" }),
    signal: AbortSignal.timeout(10_000),
  });
  return (await res.json()) as {
    device_code: string;
    user_code: string;
    verification_uri: string;
    expires_in: number;
    interval: number;
  };
}

