const formatters = new Map<string, Intl.NumberFormat>();

function formatterFor(currency: string, locale: string) {
  const key = `${locale}:${currency}`;
  let f = formatters.get(key);
  if (!f) {
    f = new Intl.NumberFormat(locale, { style: "currency", currency });
    formatters.set(key, f);
  }
  return f;
}

export function formatMoney(cents: number, currency: string, locale = "en-CA"): string {
  const digits = formatterFor(currency, locale).resolvedOptions().maximumFractionDigits ?? 2;
  return formatterFor(currency, locale).format(cents / 10 ** digits);
}

