/**
 * File uploads go directly to S3 with presigned URLs from POST /v1/uploads.
 * The API never receives file bytes: it validates the request, creates an
 * `attachments` row in state "pending", and returns a presigned PUT URL.
 * The client PUTs the file to S3, then calls POST /v1/uploads/:id/complete.
 */
import { Router } from "express";
import { PutObjectCommand } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { s3, BUCKET } from "../lib/s3.js";
import { uploadRequest } from "../schemas/uploads.js";
import { db } from "../db.js";

export const uploads = Router();

uploads.post("/", async (req, res) => {
  const body = uploadRequest.parse(req.body);
  const key = `attachments/${req.auth.orgId}/${crypto.randomUUID()}/${body.filename}`;
  const [row] = await db.insertAttachment({ orgId: req.auth.orgId, key, status: "pending" });
  const url = await getSignedUrl(
    s3,
    new PutObjectCommand({ Bucket: BUCKET, Key: key, ContentType: body.contentType }),
    { expiresIn: 300 },
  );
  res.status(201).json({ id: row.id, url, expiresIn: 300 });
});

uploads.post("/:id/complete", async (req, res) => {
  await db.markAttachmentUploaded(req.params.id, req.auth.orgId);
  res.status(204).end();
});

