function sumAllocations(allocs: Allocation[], invoices: Map<string, Invoice>) {
  return allocs.reduce(
    (sum, a) => sum + Math.min(a.amountCents, invoices.get(a.invoiceId)!.amountCents),
    0,
  );
}

export async function reconcilePayment(payment: Payment) {
  const allocs = await db.allocationsFor(payment.id);
  const invoices = new Map(
    (await db.invoicesByIds(allocs.map((a) => a.invoiceId))).map((i) => [i.id, i]),
  );
  if (invoices.size < allocs.length) {
    logger.warn({ payment: payment.id }, `payment has ${allocs.length} allocations, ${allocs.length - invoices.size} refers to deleted invoice`);
  }
  const applied = sumAllocations(allocs, invoices);
  await db.updatePayment(payment.id, { appliedCents: applied, unappliedCents: payment.amountCents - applied });
}

