export function slugify(input: string): string {
  return input
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60);
}

export function pdfFilename(invoice: Invoice & { clientName: string }): string {
  const slug = slugify(invoice.clientName);
  return slug ? `${invoice.number}-${slug}.pdf` : `${invoice.number}.pdf`;
}

