export function reminderSubject(number: string, dueDate: string, now: Date): string {
  const due = Date.UTC(...(dueDate.split("-").map(Number) as [number, number, number]).map((v, i) => (i === 1 ? v - 1 : v)) as [number, number, number]);
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  const days = Math.round((due - today) / 86_400_000);
  const plural = (n: number) => `${n} day${n === 1 ? "" : "s"}`;
  if (days > 0) return `Reminder: ${number} is due in ${plural(days)}`;
  if (days === 0) return `Reminder: ${number} is due today`;
  return `${number} is ${plural(-days)} overdue`;
}

