const schema = z.object({
  name: z.string().trim().min(1, "Name is required").max(200),
  email: z.string().email("Enter a valid email"),
  currency: z.enum(["CAD", "USD", "EUR", "GBP"]),
  taxId: z.string().trim().max(50).optional().or(z.literal("")),
});

type Values = z.infer<typeof schema>;

export function ClientForm({ clientId, defaults }: { clientId: string; defaults: Values }) {
  const update = useUpdateClient(clientId);
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting, isDirty },
  } = useForm<Values>({ resolver: zodResolver(schema), defaultValues: defaults });

  return (
    <form onSubmit={handleSubmit((v) => update.mutateAsync(v))} className="max-w-lg space-y-4">
      <Field label="Name" error={errors.name?.message}>
        <input {...register("name")} className="input" />
      </Field>
      <Field label="Email" error={errors.email?.message}>
        <input type="email" {...register("email")} className="input" />
      </Field>
      <Field label="Currency" error={errors.currency?.message}>
        <select {...register("currency")} className="input">
          {schema.shape.currency.options.map((c) => (
            <option key={c}>{c}</option>
          ))}
        </select>
      </Field>
      <Field label="Tax ID" error={errors.taxId?.message}>
        <input {...register("taxId")} className="input" />
      </Field>
      <button type="submit" disabled={!isDirty || isSubmitting} className="btn-primary">
        {isSubmitting ? "Saving…" : "Save"}
      </button>
    </form>
  );
}
